<?php require '../common.php';startpage('Book a Room');nav('<a href="index.php">Rooms</a><a href="history.php">History</a>');$id=(int)($_GET['id']??$_POST['id']??0);$s=$conn->prepare('SELECT * FROM rooms WHERE id=?');$s->bind_param('i',$id);$s->execute();$room=$s->get_result()->fetch_assoc();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$room){$g=trim($_POST['guest']);$in=$_POST['checkin'];$out=$_POST['checkout'];$n=max(1,(int)$_POST['guests']);if($g&&$in>=date('Y-m-d')&&$out>$in){$s=$conn->prepare('INSERT INTO hotel_bookings(guest,room_id,checkin,checkout,guests) VALUES(?,?,?,?,?)');$s->bind_param('sissi',$g,$id,$in,$out,$n);$s->execute();$msg='Booking saved.';}else $msg='Enter valid details and dates.';}
if($room):?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><p><?=e($room['room_type'])?> – ₹<?=$room['price']?> per night</p><input name="guest" placeholder="Guest name" required><br>Check-in <input type="date" name="checkin" min="<?=date('Y-m-d')?>" required><br>Check-out <input type="date" name="checkout" min="<?=date('Y-m-d',strtotime('+1 day'))?>" required><br>Guests <input type="number" name="guests" min="1" value="1"><br><button>Confirm booking</button></form><?php endif;if($msg)echo '<p class="msg">'.e($msg).'</p>';endpage();?>